function leftRootRight(root: TreeNode | null): number[] {
  const out: number[] = [];
  const walk = (node: TreeNode | null): void => {
    if (!node) return;
    walk(node.left);
    out.push(node.val);
    walk(node.right);
  };
  walk(root);
  return out;
}

