function leftRootRight(root: TreeNode | null): number[] {
  const out: number[] = [];
  let cur = root;
  while (cur) {
    if (!cur.left) {
      out.push(cur.val);
      cur = cur.right;
      continue;
    }
    let pre = cur.left;
    while (pre.right && pre.right !== cur) pre = pre.right;
    if (!pre.right) {
      pre.right = cur; // temporary thread back up
      cur = cur.left;
    } else {
      pre.right = null; // left subtree done: remove the thread
      out.push(cur.val);
      cur = cur.right;
    }
  }
  return out;
}

